'use client'

import { useState, useEffect } from 'react'

export interface SessionData {
    id: string
    email: string
    nom?: string
    telephone?: string
    adresse?: string
    ville?: string
    isAdmin: boolean
}

const SESSION_COOKIE_NAME = 'nonstop-session'

export function useSession() {
    const [session, setSession] = useState<SessionData | null>(null)
    const [loading, setLoading] = useState(true)

    const checkSession = () => {
        try {
            // Read the cookie
            const cookies = document.cookie.split('; ')
            const sessionCookie = cookies.find(row => row.startsWith(`${SESSION_COOKIE_NAME}=`))

            if (sessionCookie) {
                const value = decodeURIComponent(sessionCookie.split('=')[1])
                const data = JSON.parse(value)
                setSession(data)
            } else {
                setSession(null)
            }
        } catch (error) {
            console.warn('Failed to parse session cookie on client:', error)
            setSession(null)
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        checkSession()

        // Optional: add interval to check for cookie changes
        const interval = setInterval(checkSession, 5000)
        return () => clearInterval(interval)
    }, [])

    const logout = async () => {
        try {
            await fetch('/api/session', {
                method: 'DELETE',
            })
            setSession(null)
            // Redirect or handle logout state
        } catch (error) {
            console.error('Logout failed:', error)
        }
    }

    return { session, loading, logout, refresh: checkSession }
}
